begin;

-- william-shakespeare_the-tempest (534 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_the-tempest', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","onashipatseaatempestuousnoiseofthunderan~thunderandlightningheard~55":"Num navio no mar: ouve-se um ruído tempestuoso de trovões e relâmpagos.","enterashipmasterandaboatswain~ashipmasterandaboatswain~29":"Entram um Mestre do navio e um Contramestre.","masterboatswain~masterboatswain~15":"Mestre — Contramestre!","boatswainheremasterwhatcheer~swainheremasterwhatcheer~28":"Contramestre — Aqui, mestre: que ânimo?","mastergoodspeaktothemarinersfalltotyarel~sagroundbestirbestirexit~80":"Mestre — Bom, fala aos marinheiros: mãos à obra, ligeiro, ou encalhamos: mexei-vos, mexei-vos. Sai.","entermariners~entermariners~13":"Entram Marinheiros.","boatswainheighmyheartscheerlycheerlymyhe~burstthywindifroomenough~127":"Contramestre — Eia, meus bravos! Alegria, alegria, meus bravos! Ligeiro, ligeiro! Recolhei o velacho. Atentai ao apito do mestre. Sopra, até estourares o fôlego, se houver mar para isso!","enteralonsosebastianantonioferdinandgonz~erdinandgonzaloandothers~52":"Entram Alonso, Sebastião, Antônio, Ferdinando, Gonzalo e outros.","alonsogoodboatswainhavecarewheresthemast~heresthemasterplaythemen~52":"Alonso — Bom contramestre, tende cuidado. Onde está o mestre? Fazei-vos homens.","boatswainipraynowkeepbelow~atswainipraynowkeepbelow~26":"Contramestre — Rogo-vos agora, ficai lá embaixo.","antoniowhereisthemasterboatswain~hereisthemasterboatswain~32":"Antônio — Onde está o mestre, contramestre?","boatswaindoyounothearhimyoumarourlabourk~abinsyoudoassistthestorm~72":"Contramestre — Não o ouvis? Atrapalhais o nosso trabalho: ficai em vossos camarotes: ajudais a tempestade.","gonzalonaygoodbepatient~gonzalonaygoodbepatient~23":"Gonzalo — Calma, bom homem, tende paciência.","boatswainwhentheseaishencewhatcaresthese~cabinsilencetroubleusnot~89":"Contramestre — Quando o mar tiver paciência. Fora! Que se importam esses rugidores com o nome de rei? Para o camarote: silêncio! não nos estorveis.","gonzalogoodyetrememberwhomthouhastaboard~memberwhomthouhastaboard~40":"Gonzalo — Bom homem, lembra-te contudo de quem tens a bordo.","boatswainnonethatimorelovethanmyselfyoua~eartsoutofourwayisayexit~294":"Contramestre — Ninguém a quem eu ame mais que a mim mesmo. Sois um conselheiro; se podeis mandar a esses elementos que se calem e operar a paz do momento, não puxaremos mais uma corda; usai vossa autoridade: se não podeis, agradecei por haver vivido tanto e preparai-vos em vosso camarote para a desgraça da hora, se assim suceder. Alegria, bons bravos! Fora do nosso caminho, digo. Sai.","gonzaloihavegreatcomfortfromthisfellowme~ourcaseismiserableexeunt~237":"Gonzalo — Esse sujeito me dá grande conforto: parece-me que não tem sinal de afogamento; sua compleição é perfeita forca. Firme, bom Destino, para o seu enforcamento: faze da corda de seu fado o nosso cabo, pois o nosso pouco adianta. Se ele não nasceu para ser enforcado, nosso caso é miserável. Saem.","reenterboatswain~reenterboatswain~16":"Reentra o Contramestre.","boatswaindownwiththetopmastyarelowerlowe~hantheweatherorouroffice~138":"Contramestre — Abaixo o mastro de gávea! ligeiro! mais baixo, mais baixo! Ponde-a à capa com a vela grande. Ouve-se um grito lá dentro. Praga sobre essa gritaria! são mais altos que o temporal e que o nosso ofício.","reentersebastianantonioandgonzalo~bastianantonioandgonzalo~33":"Reentram Sebastião, Antônio e Gonzalo.","yetagainwhatdoyouhereshallwegiveoeranddr~ddrownhaveyouamindtosink~61":"De novo! que fazeis aqui? Havemos de desistir e afogar-nos? Tendes vontade de afundar?","sebastianapoxoyourthroatyoubawlingblasph~asphemousincharitabledog~60":"Sebastião — Peste na tua garganta, cão berrador, blasfemo, sem caridade!","boatswainworkyouthen~boatswainworkyouthen~20":"Contramestre — Trabalhai vós, então.","antoniohangcurhangyouwhoresoninsolentnoi~idtobedrownedthanthouart~84":"Antônio — Enforcado, cachorro! enforcado, filho de uma cadela, insolente barulhento! Temos menos medo de nos afogar do que tu.","gonzaloillwarranthimfordrowningthoughthe~leakyasanunstanchedwench~100":"Gonzalo — Garanto que ele não morre afogado, ainda que o navio não fosse mais forte que uma casca de noz e fizesse tanta água quanto uma moça sem estancamento.","boatswainlayheraholdaholdsethertwocourse~esofftoseaagainlayheroff~63":"Contramestre — Ponde-a à orça, à orça! largai as duas velas ao mar outra vez; afastai-a!","entermarinerswet~entermarinerswet~16":"Entram Marinheiros molhados.","marinersalllosttoprayerstoprayersalllost~oprayerstoprayersalllost~40":"Marinheiros — Tudo perdido! às orações, às orações! tudo perdido!","boatswainwhatmustourmouthsbecold~nwhatmustourmouthsbecold~32":"Contramestre — Quê, nossas bocas hão de esfriar?","gonzalothekingandprinceatprayersletsassi~themforourcaseisastheirs~66":"Gonzalo — O rei e o príncipe em orações! ajudemo-los, \n Pois o nosso caso é o deles.","sebastianimoutofpatience~sebastianimoutofpatience~24":"Sebastião — Perdi a paciência.","antoniowearemerelycheatedofourlivesbydru~ningthewashingoftentides~113":"Antônio — Somos meramente trapaceados em nossas vidas por bêbados: \n Este rufião de bocarra — quisera que jazesses afogado \n A lavagem de dez marés!","gonzalohellbehangdyetthougheverydropofwa~andgapeatwidesttogluthim~81":"Gonzalo — Ele ainda será enforcado, \n Ainda que cada gota d’água jure contra isso \n E se abra o mais que possa para o engolir.","aconfusednoisewithinmercyonuswesplitwesp~herwesplitwesplitwesplit~104":"Ouve-se um ruído confuso lá dentro: “Misericórdia!” \n “Estamos nos partindo, nos partindo!” — “Adeus, minha mulher e meus filhos!” — \n “Adeus, irmão!” — “Estamos nos partindo, nos partindo, nos partindo!”","antonioletsallsinkwiththeking~ioletsallsinkwiththeking~29":"Antônio — Afundemos todos com o rei.","sebastianletstakeleaveofhimexeuntantonio~xeuntantonioandsebastian~52":"Sebastião — Vamos despedir-nos dele. Saem Antônio e Sebastião.","gonzalonowwouldigiveathousandfurlongsofs~ldfaindieadrydeathexeunt~142":"Gonzalo — Agora eu daria mil estádios de mar por um acre de terra estéril, urze comprida, tojo castanho, qualquer coisa. Seja feita a vontade lá de cima! mas eu preferiria morrer de morte seca. Saem.","sceneii~sceneii~7":"Cena II","theislandbeforeprosperoscell~slandbeforeprosperoscell~28":"A ilha. Diante da gruta de Próspero.","enterprosperoandmiranda~enterprosperoandmiranda~23":"Entram Próspero e Miranda.","mirandaifbyyourartmydearestfatheryouhave~fraughtingsoulswithinher~444":"Miranda — Se por vossa arte, meu querido pai, fizestes \n Estas águas bravias rugirem assim, acalmai-as. \n O céu, parece, derramaria piche fedorento, \n Não fosse o mar, subindo até a face do firmamento, \n Apagar-lhe o fogo. Oh, eu sofri \n Com aqueles que vi sofrer: um nobre navio, \n Que trazia, sem dúvida, alguma nobre criatura, \n Feito em pedaços. Oh, o grito bateu \n Contra o meu próprio coração. Pobres almas, pereceram. \n Se eu fosse algum deus de poder, teria \n Afundado o mar dentro da terra antes que \n Ele engolisse assim o bom navio e \n As almas que o carregavam.","prosperobecollectednomoreamazementtellyo~oushearttheresnoharmdone~70":"Prospero — Acalma-te: \n Basta de espanto: dize a teu coração compadecido \n Que nenhum mal foi feito.","mirandaowoetheday~mirandaowoetheday~17":"Miranda — Oh, ai do dia!","prosperonoharmihavedonenothingbutincareo~ellandthynogreaterfather~199":"Prospero — Nenhum mal. \n Nada fiz senão por cuidado de ti, \n De ti, querida, ti, minha filha, que \n Ignoras o que és, nada sabendo \n De onde sou, nem que sou mais do que \n Prospero, senhor de uma pobríssima cela, \n E teu pai não maior.","mirandamoretoknowdidnevermeddlewithmytho~evermeddlewithmythoughts~45":"Miranda — Saber mais \n Nunca se meteu em meus pensamentos.","prosperotistimeishouldinformtheefartherl~orthoumustnowknowfarther~398":"Prospero — É tempo \n De informar-te mais. Empresta-me a mão, \n E tira de mim o meu manto mágico. Assim: Depõe o manto. \n Jaze aí, minha arte. Enxuga os olhos; consola-te. \n O horrendo espetáculo do naufrágio, que tocou \n A própria virtude da compaixão em ti, \n Eu o dispus, com tal providência em minha arte, \n Tão seguramente que não há alma— \n Não, nem tanta perdição quanto um fio de cabelo \n Sucedeu a criatura alguma na nau \n Que ouviste gritar e viste afundar. Senta-te; \n Pois deves agora saber mais.","mirandayouhaveoftenbeguntotellmewhatiamb~tionconcludingstaynotyet~99":"Miranda — Muitas vezes \n Começastes a dizer-me o que sou, mas parastes \n E deixastes-me a uma indagação inútil, \n Concluindo: “Espera: ainda não.”","prosperothehoursnowcometheveryminutebids~uwastnotoutthreeyearsold~173":"Prospero — A hora agora chegou; \n O próprio minuto te manda abrir o ouvido; \n Obedece e sê atenta. Podes lembrar \n De um tempo antes de virmos a esta cela? \n Não creio que possas, pois então não tinhas \n Completado três anos.","mirandacertainlysirican~mirandacertainlysirican~23":"Miranda — Certamente, senhor, posso.","prosperobywhatbyanyotherhouseorpersonofa~thkeptwiththyremembrance~91":"Prospero — Por quê? Por outra casa ou pessoa? \n De qualquer coisa dize-me a imagem que \n Se manteve em tua lembrança.","mirandatisfaroffandratherlikeadreamthana~ivewomenoncethattendedme~113":"Miranda — É longínquo \n E mais como um sonho que uma certeza \n Que minha memória garanta. Não tive eu \n Quatro ou cinco mulheres que me serviam?","prosperothouhadstandmoremirandabuthowisi~wthoucamestherethoumayst~175":"Prospero — Tiveste, e mais, Miranda. Mas como é \n Que isso vive em tua mente? Que mais vês \n No escuro recuo e abismo do tempo? \n Se algo lembras antes de teres vindo aqui, \n Como vieste aqui poderás lembrar.","mirandabutthatidonot~mirandabutthatidonot~20":"Miranda — Mas isso não lembro.","prosperotwelveyearsincemirandatwelveyear~ofmilanandaprinceofpower~88":"Prospero — Há doze anos, Miranda, há doze anos, \n Teu pai era o Duque de Milão e \n Príncipe de poder.","mirandasirarenotyoumyfather~andasirarenotyoumyfather~27":"Miranda — Senhor, não sois vós meu pai?","prosperothymotherwasapieceofvirtueandshe~andprincessnoworseissued~130":"Prospero — Tua mãe era uma obra de virtude, e \n Disse que eras minha filha; e teu pai \n Era Duque de Milão; e tu, sua única herdeira \n E princesa de não pior linhagem.","mirandaotheheavenswhatfoulplayhadwethatw~thenceorblessedwastwedid~73":"Miranda — Oh, céus! \n Que jogo sujo sofremos, para vir de lá? \n Ou foi bênção que viéssemos?","prosperobothbothmygirlbyfoulplayasthousa~cebutblessedlyholphither~83":"Prospero — Ambos, ambos, minha menina: \n Por jogo sujo, como dizes, fomos de lá lançados, \n Mas abençoadamente ajudados até aqui.","mirandaomyheartbleedstothinkotheteenthat~embrancepleaseyoufarther~95":"Miranda — Oh, meu coração sangra \n Ao pensar na dor a que vos reduzi, \n Que se foi de minha lembrança! Prossegui, por favor.","prosperomybrotherandthyunclecalldantonio~lseuncledostthouattendme~423":"Prospero — Meu irmão e teu tio, chamado Antonio— \n Peço-te, ouve-me—que um irmão pudesse \n Ser tão pérfido!—ele a quem, depois de ti, \n De todo o mundo mais amei e a quem confiei \n O governo de meu estado; que naquele tempo \n Entre todas as senhorias era a primeira \n E Prospero o primeiro duque, assim reputado \n Em dignidade, e nas artes liberais \n Sem paralelo; sendo elas todo o meu estudo, \n O governo lancei sobre meu irmão \n E tornei-me estranho a meu estado, transportado \n E arrebatado em estudos secretos. Teu falso tio— \n Estás atenta a mim?","mirandasirmostheedfully~mirandasirmostheedfully~23":"Miranda — Senhor, com o maior cuidado.","prosperobeingonceperfectedhowtograntsuit~ureoutontthouattendstnot~318":"Prospero — Uma vez perfeito em como conceder pedidos, \n Como negá-los, a quem promover e a quem \n Podar por sobressair, recriou \n As criaturas que eram minhas, digo, ou as mudou, \n Ou então as formou de novo; tendo ambas \n A chave de oficial e ofício, pôs todos os corações do estado \n No tom que agradava a seu ouvido; de modo que agora era \n A hera que escondera meu tronco principesco, \n E sugara dele minha verdura. Não prestas atenção.","mirandaogoodsirido~mirandaogoodsirido~18":"Miranda — Oh, bom senhor, presto.","prosperoipraytheemarkmeithusneglectingwo~itiongrowingdostthouhear~599":"Prospero — Peço-te, ouve-me. \n Eu, assim negligenciando fins mundanos, todo dedicado \n À reclusão e ao aprimoramento de minha mente \n Com aquilo que, só por ser tão retirado, \n Sobrepujava toda estima popular, em meu falso irmão \n Despertei uma natureza má; e minha confiança, \n Como bom pai, gerou nele \n Uma falsidade em seu contrário tão grande \n Quanto era minha confiança; que de fato não tinha limite, \n Uma confiança sem fronteira. Sendo ele assim senhoreado, \n Não só do que minha renda rendia, \n Mas do que meu poder poderia exigir, como alguém \n Que, tendo à verdade, por contá-la, \n Feito tal pecador de sua memória \n Que acredita em sua própria mentira, passou a crer \n Que era de fato o duque; pela substituição, \n E exercendo a face externa da realeza, \n Com toda prerrogativa: daí sua ambição crescendo— \n Ouves?","mirandayourtalesirwouldcuredeafness~talesirwouldcuredeafness~35":"Miranda — Vossa história, senhor, curaria a surdez.","prosperotohavenoscreenbetweenthisparthep~lantomostignoblestooping~334":"Prospero — Para não ter biombo entre este papel que representava \n E aquele para quem o representava, quis necessariamente ser \n Milão absoluto. A mim, pobre homem, minha biblioteca \n Era ducado bastante grande: de reais temporais \n Julga-me agora incapaz; aliou-se— \n Tão sedento estava de mando—ao Rei de Nápoles \n Para lhe dar tributo anual, prestar-lhe homenagem, \n Sujeitar sua coroinha à coroa dele e dobrar \n O ducado ainda não dobrado—ai, pobre Milão!— \n À mais ignóbil prostração.","mirandaotheheavens~mirandaotheheavens~18":"Miranda — Oh, céus!","prosperomarkhisconditionandtheeventthent~lmeifthismightbeabrother~66":"Prospero — Nota sua condição e o resultado; depois dize-me \n Se isto poderia ser um irmão.","mirandaishouldsintothinkbutnoblyofmygran~oodwombshavebornebadsons~72":"Miranda — Eu pecaria \n Se pensasse senão nobremente de minha avó: \n Bons ventres geraram maus filhos.","prosperonowtheconditionthekingofnaplesbe~thencemeandthycryingself~408":"Prospero — Agora a condição. \n O Rei de Nápoles, sendo meu inimigo \n Inveterado, atende ao pedido de meu irmão; \n Que era que ele, em troca das promessas \n De homenagem e não sei quanto tributo, \n Extirpasse logo a mim e aos meus \n Do ducado e conferisse a bela Milão \n Com todas as honras a meu irmão: então, \n Levantado um exército traidor, numa meia-noite \n Fadada ao intento, Antonio abriu \n As portas de Milão, e, no silêncio da escuridão, \n Os ministros para isso destacados arrebataram dali \n A mim e a ti, que chorava.","mirandaalackforpityinotrememberinghowicr~intthatwringsmineeyestot~97":"Miranda — Ai, que piedade! \n Eu, sem lembrar como então chorei, \n Chorarei de novo: é uma insinuação \n Que me arranca os olhos às lágrimas.","prosperohearalittlefurtherandthenillbrin~storyweremostimpertinent~122":"Prospero — Ouve um pouco mais \n E então te conduzirei ao negócio presente \n Que agora está sobre nós; sem o qual esta história \n Seria de todo impertinente.","mirandawhereforedidtheynotthathourdestro~theynotthathourdestroyus~43":"Miranda — Por que não \n Nos destruíram naquela hora?","prosperowelldemandedwenchmytaleprovokest~againdidusbutlovingwrong~418":"Prospero — Bem perguntado, menina: \n Minha história provoca essa pergunta. Querida, não ousaram, \n Tão caro era o amor que meu povo me tinha, nem pôr \n Marca tão sangrenta no caso, mas \n Com cores mais belas pintaram seus fins sujos. \n Em suma, arrastaram-nos a bordo de uma barca, \n Levaram-nos algumas léguas mar adentro; onde prepararam \n Uma carcaça podre de barco, sem cordame, \n Nem aparelho, vela ou mastro; os próprios ratos \n Por instinto a haviam abandonado: ali nos içaram, \n Para clamar ao mar que rugia para nós, para suspirar \n Aos ventos cuja piedade, suspirando de volta, \n Nos fazia só amorosa injúria.","mirandaalackwhattroublewasithentoyou~whattroublewasithentoyou~36":"Miranda — Ai, que incômodo \n Fui eu então para vós!","prosperooacherubinthouwastthatdidpreserv~upagainstwhatshouldensue~209":"Prospero — Oh, um querubim \n Foste tu que me preservou. Sorriste, \n Infundida de uma fortaleza do céu, \n Quando eu ornava o mar com gotas bem salgadas, \n Gemia sob meu fardo; o que ergueu em mim \n Um ânimo de suportar, para me manter firme \n Contra o que viesse.","mirandahowcameweashore~mirandahowcameweashore~22":"Miranda — Como chegamos à terra?","prosperobyprovidencedivinesomefoodwehada~thatiprizeabovemydukedom~312":"Prospero — Pela Providência divina. \n Algum alimento tínhamos e alguma água fresca que \n Um nobre napolitano, Gonzalo, \n Por sua caridade, sendo então designado \n Chefe deste plano, nos deu, com \n Ricas vestes, linhos, tecidos e coisas necessárias, \n Que desde então muito serviram; e assim, de sua gentileza, \n Sabendo que eu amava meus livros, forneceu-me \n De minha própria biblioteca volumes que \n Estimo acima do meu ducado.","mirandawouldimightbuteverseethatman~dimightbuteverseethatman~35":"Miranda — Quisera eu \n Poder ver um dia esse homem!","prosperonowiariseresumeshismantlesitstil~ursandtutorsnotsocareful~212":"Prospero — Agora me levanto: Retoma o manto. \n Fica sentada e ouve o último de nossa mágoa marítima. \n Nesta ilha chegamos; e aqui \n Fiz eu, teu mestre-escola, mais proveito a ti \n Do que outras princesas podem ter, que têm mais tempo \n Para horas mais vãs e preceptores menos cuidadosos.","mirandaheavensthankyoufortandnowiprayyou~onforraisingthisseastorm~101":"Miranda — Os céus vos agradeçam! E agora, peço-vos, senhor, \n Pois ainda me bate na mente, a vossa razão \n Para levantar esta tempestade no mar?","prosperoknowthusfarforthbyaccidentmostst~dynowapproachmyarielcome~389":"Prospero — Sabe até aqui. \n Por acidente estranhíssimo, a generosa Fortuna, \n Agora minha querida dama, trouxe meus inimigos \n A esta praia; e por minha presciência \n Vejo que meu zênite depende \n De uma estrela auspiciosíssima, cuja influência, \n Se agora não cortejar mas omitir, minhas fortunas \n Ficarão para sempre abatidas. Aqui cessem mais perguntas: \n Estás inclinada a dormir; é uma boa moleza, \n E dá-lhe passagem: sei que não podes escolher. Miranda adormece. \n Vem, servo, vem. Estou pronto agora. \n Aproxima-te, meu Ariel, vem.","enterariel~enterariel~10":"Entra Ariel.","arielallhailgreatmastergravesirhailicome~askarielandallhisquality~159":"Ariel — Salve, grande mestre! Grave senhor, salve! Venho \n Atender a teu melhor prazer; seja voar, \n Nadar, mergulhar no fogo, cavalgar \n Nas nuvens encrespadas, a teu forte mando entrega-se \n Ariel e toda a sua qualidade.","prosperohastthouspiritperformdtopointthe~tthetempestthatibadethee~60":"Prospero — Executaste, espírito, \n Com exatidão a tempestade que te ordenei?","arieltoeveryarticleiboardedthekingsshipn~eyeahisdreadtridentshake~409":"Ariel — Em cada artigo. \n Abordei a nau do rei; ora na proa, \n Ora no meio, no convés, em cada camarote, \n Inflamei espanto: às vezes me dividia, \n E ardia em muitos lugares; no mastro de gávea, \n Nas vergas e no gurupés, flamejava distintamente, \n Depois me encontrava e juntava. Os relâmpagos de Jove, precursores \n Dos tremendos trovões, mais instantâneos \n E mais velozes que a vista não eram; o fogo e os estalos \n Do rugido sulfuroso faziam o poderosíssimo Netuno \n Parecer sitiado e suas ousadas ondas tremer, \n Sim, seu temível tridente sacudir.","prosperomybravespiritwhowassofirmsoconst~lwouldnotinfecthisreason~78":"Prospero — Meu valente espírito! \n Quem foi tão firme, tão constante, que este tumulto \n Não lhe infectasse a razão?","arielnotasoulbutfeltafeverofthemadandpla~tyandallthedevilsarehere~255":"Ariel — Nem uma alma \n Que não sentisse uma febre de loucos e não fizesse \n Algumas peripécias de desespero. Todos, menos os marinheiros, \n Mergulharam na salmoura espumante e abandonaram a nau, \n Então toda em chamas comigo: o filho do rei, Ferdinand, \n Com os cabelos em pé—então como juncos, não cabelos— \n Foi o primeiro homem que saltou; gritou: “O inferno está vazio \n E todos os demônios estão aqui.”","prosperowhythatsmyspiritbutwasnotthisnig~itbutwasnotthisnighshore~46":"Prospero — Ora, esse é o meu espírito! \n Mas não foi perto da costa?","arielclosebymymaster~arielclosebymymaster~20":"Ariel — Bem junto, meu mestre.","prosperobutaretheyarielsafe~sperobutaretheyarielsafe~27":"Prospero — Mas estão, Ariel, salvos?","arielnotahairperishdontheirsustaininggar~tinghisarmsinthissadknot~245":"Ariel — Nem um cabelo pereceu; \n Em suas vestes de sustento nem uma mácula, \n Mas mais frescas que antes: e, como me mandaste, \n Em bandos os dispersei pela ilha. \n O filho do rei pus em terra à parte; \n A quem deixei refrescando o ar com suspiros \n Num canto remoto da ilha e sentado, \n Os braços neste triste nó.","prosperoofthekingsshipthemarinerssayhowt~edandalltherestothefleet~77":"Prospero — Da nau do rei \n Dize como dispuseste os marinheiros \n E todo o resto da frota.","arielsafelyinharbouristhekingsshipinthed~dandhisgreatpersonperish~384":"Ariel — Em segurança no porto \n Está a nau do rei; na funda enseada, onde outrora \n Me chamaste à meia-noite para colher orvalho \n Das sempre agitadas Bermudas, ali está escondida: \n Os marinheiros todos arrumados sob as escotilhas; \n Os quais, com um encanto unido ao labor sofrido, \n Deixei adormecidos; e quanto ao resto da frota \n Que dispersei, todos se reuniram de novo \n E estão sobre as ondas do Mediterrâneo, \n Rumo tristemente a Nápoles, \n Supondo que viram a nau do rei naufragada \n E sua grande pessoa perecer.","prosperoarielthychargeexactlyisperformdb~workwhatisthetimeotheday~76":"Prospero — Ariel, tua tarefa \n Foi exatamente cumprida: mas há mais trabalho. \n Que hora do dia é?","arielpastthemidseason~arielpastthemidseason~21":"Ariel — Passado o meio-dia.","prosperoatleasttwoglassesthetimetwixtsix~othbespentmostpreciously~79":"Prospero — Ao menos duas ampulhetas. O tempo entre seis e agora \n Deve ser por nós dois gasto preciosíssimamente.","arielistheremoretoilsincethoudostgivemep~dwhichisnotyetperformdme~104":"Ariel — Há mais labuta? Já que me dás penas, \n Deixa-me lembrar-te o que prometeste, \n O que ainda não me foi cumprido.","prosperohownowmoodywhatistthoucanstdeman~dywhatistthoucanstdemand~41":"Prospero — Como? Rabugento? \n Que podes exigir?","arielmyliberty~arielmyliberty~14":"Ariel — Minha liberdade.","prosperobeforethetimebeoutnomore~beforethetimebeoutnomore~32":"Prospero — Antes de findar o tempo? Basta!","arielipritheerememberihavedonetheeworthy~promisetobatemeafullyear~147":"Ariel — Peço-te, \n Lembra que te prestei serviço digno; \n Não te contei mentiras, não cometi erros, servi \n Sem rancor nem resmungos: prometeste \n Abater-me um ano inteiro.","prosperodostthouforgetfromwhatatormentid~whatatormentididfreethee~50":"Prospero — Esqueces \n De que tormento te libertei?","arielno~arielno~7":"Ariel — Não.","prosperothoudostandthinkstitmuchtotreadt~thwhenitisbakedwithfrost~145":"Prospero — Esqueces, e achas muito pisar o lodo \n Do fundo salgado, \n Correr sobre o vento cortante do norte, \n Fazer meu serviço nas veias da terra \n Quando está endurecida de gelo.","arielidonotsir~arielidonotsir~14":"Ariel — Não acho, senhor.","prosperothouliestmalignantthinghastthouf~toahoophastthouforgother~115":"Prospero — Mentes, coisa maligna! Esqueceste \n A imunda bruxa Sycorax, que de idade e inveja \n Se tornara um arco? Esqueceste dela?","arielnosir~arielnosir~10":"Ariel — Não, senhor.","prosperothouhastwherewasshebornspeaktell~erewasshebornspeaktellme~42":"Prospero — Esqueceste. Onde nasceu? Fala; dize-me.","arielsirinargier~arielsirinargier~16":"Ariel — Senhor, em Argel.","prosperoowasshesoimustonceinamonthrecoun~takeherlifeisnotthistrue~237":"Prospero — Oh, foi assim? Devo \n Uma vez ao mês recontar o que foste, \n O que esqueces. Esta maldita bruxa Sycorax, \n Por malfeitos múltiplos e feitiçarias terríveis \n Demais para ouvido humano, de Argel, \n Sabes, foi banida: por uma coisa que fez \n Não lhe quiseram tirar a vida. Não é verdade?","arielaysir~arielaysir~10":"Ariel — Sim, senhor.","prosperothisblueeyedhagwashitherbroughtw~othonourdwithahumanshape~543":"Prospero — Esta bruxa de olhos azuis foi trazida aqui grávida \n E aqui deixada pelos marinheiros. Tu, meu escravo, \n Como tu mesmo relatas, eras então seu servo; \n E, porque eras espírito delicado demais \n Para cumprir suas ordens terrenas e abomináveis, \n Recusando seus grandes mandados, ela te confinou, \n Com ajuda de seus ministros mais potentes \n E em sua mais implacável ira, \n Num pinheiro fendido; em cuja fenda \n Aprisionado ficaste penosamente \n Uma dúzia de anos; nesse espaço ela morreu \n E deixou-te lá; onde exalavas teus gemidos \n Tão depressa quanto batem as rodas de moinho. Então esta ilha— \n Salvo o filho que ela aqui pariu, \n Um cachorro sardento nascido de bruxa—não era honrada com \n Forma humana.","arielyescalibanherson~arielyescalibanherson~21":"Ariel — Sim, Caliban, seu filho.","prosperodullthingisaysohethatcalibanwhom~gapethepineandlettheeout~287":"Prospero — Coisa obtusa, digo que sim; ele, aquele Caliban \n Que agora mantenho em serviço. Tu melhor sabes \n Em que tormento te encontrei; teus gemidos \n Faziam uivar os lobos e penetravam o peito \n De ursos sempre irados: era um tormento \n Para lançar sobre os condenados, que Sycorax \n Não pôde desfazer: foi minha arte, \n Quando cheguei e te ouvi, que fez abrir \n O pinheiro e te deixou sair.","arielithanktheemaster~arielithanktheemaster~21":"Ariel — Agradeço-te, mestre.","prosperoifthoumoremurmurstiwillrendanoak~sthowldawaytwelvewinters~103":"Prospero — Se murmurares mais, fenderei um carvalho \n E te cravarei em suas entranhas nodosas até que \n Tenhas uivado doze invernos.","arielpardonmasteriwillbecorrespondenttoc~ndanddomyspiritinggently~68":"Ariel — Perdão, mestre; \n Serei correspondente ao mando \n E farei meu espiritismo com brandura.","prosperodosoandaftertwodaysiwilldischarg~wodaysiwilldischargethee~45":"Prospero — Faze-o, e depois de dois dias \n Te dispensarei.","arielthatsmynoblemasterwhatshallidosaywh~llidosaywhatwhatshallido~54":"Ariel — Eis meu nobre mestre! \n Que farei? Dize o quê; que farei?","prosperogomakethyselflikeanymphotheseabe~kethouhastsleptwellawake~199":"Prospero — Vai fazer-te como uma ninfa do mar: sê sujeito \n A nenhuma vista senão a tua e a minha, invisível \n A todo outro globo ocular. Vai, toma esta forma \n E vem aqui com ela: vai, daqui com diligência! Sai Ariel. \n Desperta, querido coração, desperta! Dormiste bem; \n Desperta!","mirandathestrangenessofyourstoryputheavi~ourstoryputheavinessinme~48":"Miranda — A estranheza de vossa história pôs \n Peso em mim.","prosperoshakeitoffcomeonwellvisitcaliban~oneveryieldsuskindanswer~73":"Prospero — Sacode-o. Vem; \n Visitaremos Caliban, meu escravo, que nunca \n Nos dá resposta amável.","mirandatisavillainsiridonotlovetolookon~ainsiridonotlovetolookon~39":"Miranda — É um vilão, senhor, \n A que não gosto de olhar.","prosperobutastiswecannotmisshimhedoesmak~alibanthouearththouspeak~128":"Prospero — Mas, sendo como é, \n Não podemos passar sem ele: faz nosso fogo, \n Traz nossa lenha e serve em ofícios \n Que nos aproveitam. Ei, olá! Escravo! Caliban! \n Tu, terra, tu! Fala.","calibanwithinthereswoodenoughwithin~inthereswoodenoughwithin~35":"Caliban — Lá dentro. Há lenha bastante aqui dentro.","prosperocomeforthisaytheresotherbusiness~theecomethoutortoisewhen~67":"Prospero — Sai, digo! Há outro serviço para ti: \n Vem, tu, tartaruga! Quando?","reenterariellikeawaternymph~nterariellikeawaternymph~27":"Reentra Ariel como ninfa das águas.","fineapparitionmyquaintarielharkinthineea~uaintarielharkinthineear~41":"Bela aparição! Meu engenhoso Ariel, \n Ouve ao ouvido.","arielmylorditshallbedoneexit~lmylorditshallbedoneexit~28":"Ariel — Meu senhor, será feito. Sai.","prosperothoupoisonousslavegotbythedevilh~ponthywickeddamcomeforth~71":"Prospero — Tu, escravo venenoso, gerado pelo próprio diabo \n Em tua mãe perversa, sai!","entercaliban~entercaliban~12":"Entra Caliban.","calibanaswickeddewaseermymotherbrushdwit~wonyeandblisteryoualloer~122":"Caliban — Tão perverso orvalho como minha mãe jamais varreu \n Com pena de corvo de pântano insalubre \n Caia sobre vós dois! Um vento do sudoeste sopre sobre vós \n E vos encha de bolhas da cabeça aos pés!","prosperoforthisbesuretonightthoushalthav~ingingthanbeesthatmadeem~218":"Prospero — Por isto, tem certeza, esta noite terás cãibras, \n Pontadas no flanco que te prenderão o fôlego; ouriços \n Durante aquele vasto da noite em que podem agir, \n Todos se exercitarão em ti; serás beliscado \n Tão denso quanto favo de mel, cada beliscão mais ferroante \n Que as abelhas que os fizeram.","calibanimusteatmydinnerthisislandsmineby~pfrommetherestotheisland~510":"Caliban — Preciso comer meu jantar. \n Esta ilha é minha, por Sycorax, minha mãe, \n Que tu me tomas. Quando chegaste a princípio, \n Afagavas-me e fazias muito de mim, davas-me \n Água com bagas dentro, e ensinavas-me como \n Nomear a luz maior e como a menor, \n Que ardem de dia e de noite: e então eu te amava \n E mostrei-te todas as qualidades da ilha, \n As fontes frescas, as salinas, o lugar estéril e o fértil: \n Maldito seja eu que o fiz! Todos os feitiços \n De Sycorax, sapos, besouros, morcegos, caiam sobre vós! \n Pois sou todos os súditos que tendes, \n Eu que fui primeiro meu próprio rei: e aqui me encurralais \n Nesta rocha dura, enquanto me guardais fora \n O resto da ilha.","prosperothoumostlyingslavewhomstripesmay~iolatethehonourofmychild~165":"Prospero — Tu, escravo mentirosíssimo, \n Que castigos podem mover, não bondade! Tratei-te, \n Imundície que és, com cuidado humano, e alojei-te \n Em minha própria cela, até que procuraste violar \n A honra de minha filha.","calibanohoohowouldthadbeendonethoudidstp~elsethisislewithcalibans~83":"Caliban — Oh ho, oh ho! Tivesse sido feito! \n Tu o impediste; eu teria povoado \n Esta ilha de Calibans.","prosperoabhorredslavewhichanyprintofgood~tdeservedmorethanaprison~424":"Prospero — Escravo abominado, \n Que nenhuma marca de bondade quer receber, \n Capaz de todo mal! Tive pena de ti, \n Esforcei-me para te fazer falar, ensinei-te a cada hora \n Uma coisa ou outra: quando tu, selvagem, não \n Sabias teu próprio sentido, mas tagarelavas como \n Uma coisa bem bruta, dotei teus propósitos \n De palavras que os deram a conhecer. Mas tua raça vil, \n Embora aprendesses, tinha nela algo que as boas naturezas \n Não podiam suportar; por isso foste \n Merecidamente confinado nesta rocha, \n Tu que merecias mais que uma prisão.","calibanyoutaughtmelanguageandmyprofitont~orlearningmeyourlanguage~100":"Caliban — Ensinaste-me a linguagem; e meu proveito dela \n É saber amaldiçoar. A peste vermelha vos leve \n Por me ensinardes vossa linguagem!","prosperohagseedhencefetchusinfuelandbequ~astsshalltrembleatthydin~225":"Prospero — Semente de bruxa, fora! \n Traze-nos combustível; e sê rápido, é bom para ti, \n Para atender a outro serviço. Dás de ombros, malícia? \n Se negligenciares ou fizeres a contragosto \n O que mando, torturar-te-ei com antigas cãibras, \n Encherei-te todos os ossos de dores, far-te-ei rugir \n De modo que as feras tremam do teu estrondo.","calibannopraytheeasideimustobeyhisartiso~tebosandmakeavassalofhim~99":"Caliban — Não, peço-te. \n À parte. Devo obedecer: sua arte é de tal poder \n Que dominaria o deus de minha mãe, Setebos, \n E faria dele um vassalo.","prosperososlavehenceexitcaliban~ososlavehenceexitcaliban~31":"Prospero — Assim, escravo; fora! Sai Caliban.","reenterarielinvisibleplayingandsingingfe~ingingferdinandfollowing~56":"Reentra Ariel, invisível, tocando e cantando; Ferdinand o segue.","arielssong~arielssong~10":"Canção de Ariel.","comeuntotheseyellowsandsandthentakehands~owthewatchdogsbarkbowwow~192":"Vinde a estas areias amarelas, \n E então dai as mãos: \n Feitas as reverências e beijado \n O mar bravio em silêncio, \n Dançai ligeiro aqui e ali; \n E, doces espíritos, levai o refrão. \n Refrão disperso. Ouvi, ouvi! \n Au-au. \n Os cães de guarda ladram: \n Au-au.","arielharkharkihearthestrainofstruttingch~ticleercrycockadiddledow~66":"Ariel — Ouvi, ouvi! Ouço \n O canto do galo orgulhoso \n Gritar: Cocoricó.","ferdinandwhereshouldthismusicbeitheairor~uttisgonenoitbeginsagain~289":"Ferdinand — Onde estaria esta música? No ar ou na terra? \n Já não soa: e, por certo, serve \n A algum deus da ilha. Sentado numa colina, \n Chorando de novo o naufrágio do rei meu pai, \n Esta música esgueirou-se por mim sobre as águas, \n Abrandando tanto a fúria delas quanto minha paixão \n Com sua doce melodia: daí a segui, \n Ou antes ela me atraiu. Mas cessou. \n Não, recomeça.","arielsings~arielsings~10":"Ariel canta.","fullfathomfivethyfatherliesofhisbonesare~ghisknellburthendingdong~194":"A cinco braças jaz teu pai; \n De seus ossos coral se fez; \n Pérolas são os olhos que ele teve: \n Nada dele que desfaz \n Mas sofre uma mudança marinha \n Em algo rico e estranho. \n Ninfas do mar a toda hora lhe dobram os sinos: \n Refrão. Din-dom.","arielharknowihearthemdingdongbell~nowihearthemdingdongbell~33":"Ariel — Ouvi! Agora os ouço—Din-dom, sino.","ferdinandthedittydoesremembermydrowndfat~rthowesihearitnowaboveme~108":"Ferdinand — A cantiga lembra meu pai afogado. \n Isto não é obra mortal, nem som \n Que a terra deva. Ouço-o agora acima de mim.","prosperothefringedcurtainsofthineeyeadva~eandsaywhatthouseestyond~66":"Prospero — As cortinas franjadas de teus olhos ergue \n E dize o que vês ali.","mirandawhatistaspiritlordhowitlooksabout~sabraveformbuttisaspirit~84":"Miranda — Que é? Um espírito? \n Senhor, como olha ao redor! Crede-me, senhor, \n Tem bela forma. Mas é um espírito.","prosperonowenchiteatsandsleepsandhathsuc~wsandstraysabouttofindem~221":"Prospero — Não, menina; come e dorme e tem tais sentidos \n Como nós, tais. Este galante que vês \n Estava no naufrágio; e, não fosse estar um tanto manchado \n De dor, que é a ferrugem da beleza, poderias chamá-lo \n De formosa pessoa: perdeu os companheiros \n E vagueia para encontrá-los.","mirandaimightcallhimathingdivinefornothi~ngnaturalieversawsonoble~64":"Miranda — Poderia chamá-lo \n De coisa divina, pois nada natural \n Vi jamais tão nobre.","prosperoasideitgoesoniseeasmysoulprompts~theewithintwodaysforthis~89":"Prospero — À parte. Vai bem, vejo, \n Como minha alma o impele. Espírito, fino espírito! Libertar-te-ei \n Em dois dias por isto.","ferdinandmostsurethegoddessonwhomtheseai~youwonderifyoubemaidorno~213":"Ferdinand — Certamente a deusa \n A quem estes ares servem! Dignai-vos que minha prece \n Saiba se permaneceis nesta ilha; \n E que me deis alguma boa instrução \n De como me portar aqui: meu primeiro pedido, \n Que pronuncio por último, é, oh, vós, maravilha! \n Se sois donzela ou não?","mirandanowondersirbutcertainlyamaid~ndersirbutcertainlyamaid~35":"Miranda — Nenhuma maravilha, senhor; \n Mas certamente donzela.","ferdinandmylanguageheavensiamthebestofth~chwereibutwheretisspoken~83":"Ferdinand — Minha língua! Céus! \n Sou o primeiro dos que falam esta fala, \n Estivesse eu onde ela é falada.","prosperohowthebestwhatwertthouifthekingo~thekingofnaplesheardthee~56":"Prospero — Como? O primeiro? \n Que serias, se o Rei de Nápoles te ouvisse?","ferdinandasinglethingasiamnowthatwonders~eldthekingmyfatherwreckd~164":"Ferdinand — Uma coisa só, como sou agora, que se espanta \n De ouvir-vos falar de Nápoles. Ele me ouve; \n E por ouvir, choro: eu mesmo sou Nápoles, \n Que com meus olhos, nunca desde então em vazante, vi \n O rei meu pai naufragado.","mirandaalackformercy~mirandaalackformercy~20":"Miranda — Ai, por misericórdia!","ferdinandyesfaithandallhislordsthedukeof~andhisbravesonbeingtwain~69":"Ferdinand — Sim, na verdade, e todos os seus lordes; o Duque de Milão \n E seu valente filho sendo dois.","prosperoasidethedukeofmilanandhismorebra~neyourselfsomewrongaword~214":"Prospero — À parte. O Duque de Milão \n E sua filha ainda mais valente poderiam desmenti-lo, \n Se agora fosse oportuno fazê-lo. À primeira vista \n Trocaram olhares. Delicado Ariel, \n Libertar-te-ei por isto. A Ferdinand. Uma palavra, bom senhor; \n Temo que vos tenhais feito algum agravo: uma palavra.","mirandawhyspeaksmyfathersoungentlythisis~yfathertobeinclinedmyway~119":"Miranda — Por que fala meu pai tão asperamente? Este \n É o terceiro homem que jamais vi, o primeiro \n Por quem jamais suspirei: que a piedade mova meu pai \n A inclinar-se a meu favor!","ferdinandoifavirginandyouraffectionnotgo~lmakeyouthequeenofnaples~73":"Ferdinand — Oh, se sois virgem, \n E vossa afeição não se foi, farei de vós \n A rainha de Nápoles.","prosperosoftsironewordmoreasidetheyarebo~ytowinitfrommethelordont~273":"Prospero — Devagar, senhor! Uma palavra mais. \n À parte. Estão ambos no poder um do outro; mas este negócio ligeiro \n Devo tornar difícil, para que ganho fácil demais \n Não torne o prêmio leve. A Ferdinand. Uma palavra mais; ordeno-te \n Que me atendas: aqui usurpas \n O nome que não possuis; e te puseste \n Nesta ilha como espião, para ganhá-la \n de mim, seu senhor.","ferdinandnoasiamaman~ferdinandnoasiamaman~20":"Ferdinand — Não, assim como sou homem.","mirandatheresnothingillcandwellinsuchate~gswillstrivetodwellwitht~106":"Miranda — Nada mau pode habitar em tal templo: \n Se o espírito mau tem casa tão bela, \n As boas coisas porfiarão em habitar com ele